def compile_geo_indicator(method_id, phase, h12, anchors):
    R = TEXT_SET.catalog[method_id]
    S = R.phases[phase]
    strings = {k: v.replace('{h12}', h12) for k,v in S['Σ_geo'].items()}
    ops = []
    for op in S['draw_ops']:
        ops.append(bind(op, anchors, strings))  # endpoints on HL.*
    return strings, ops, S['style']
